class Repo { fun names() = listOf("ana", "bo", "cy") }

class GetDisplayNamesUseCase(private val repo: Repo) {
    operator fun invoke(limit: Int): List<String> =
        repo.names().take(limit).map { it.replaceFirstChar { c -> c.uppercaseChar() } }
}

fun main() {
    val getDisplayNames = GetDisplayNamesUseCase(Repo())
    println(getDisplayNames(2))
}

sealed interface DomainError {
    data object NotFound : DomainError
    data object Server : DomainError
    data class Unknown(val code: Int) : DomainError
}

fun toDomainError(code: Int): DomainError = when (code) {
    404 -> DomainError.NotFound
    in 500..599 -> DomainError.Server
    else -> DomainError.Unknown(code)
}

fun main() {
    listOf(404, 503, 418).map(::toDomainError).forEach { println(it) }
}

class GetUserUseCase @Inject constructor(
    private val repo: UserRepository
) {
    suspend operator fun invoke(id: String) = repo.getUser(id)
}

class UserRepository(private val api: UserApi) {
    suspend fun getUser(id: String): Result<User> =
        runCatching { api.getUser(id).toDomain() }
}

class FakeApi {
    var calls = 0
    fun fetch(id: Int): String { calls++; return "user$id" }
}

class UserRepository(private val api: FakeApi) {
    private val cache = mutableMapOf<Int, String>()
    fun get(id: Int, refresh: Boolean = false): String =
        if (refresh) api.fetch(id).also { cache[id] = it }
        else cache.getOrPut(id) { api.fetch(id) }
}

fun main() {
    val api = FakeApi()
    val repo = UserRepository(api)
    repo.get(1); repo.get(1); repo.get(2); repo.get(1, refresh = true); repo.get(2)
    println("calls=${api.calls}")
}
